@TestOn('vm')
library;

import 'dart:async';

import 'package:flutter_agent_harness/src/cancel_token.dart';
import 'package:flutter_agent_harness/src/context.dart';
import 'package:flutter_agent_harness/src/env/memory_execution_env.dart';
import 'package:flutter_agent_harness/src/session/session_repo.dart';
import 'package:flutter_agent_harness/src/task/subagent.dart';
import 'package:flutter_agent_harness/src/task/subagent_manager.dart';
import 'package:flutter_agent_harness/src/task/task_tool.dart';
import 'package:flutter_agent_harness/src/types.dart';
import 'package:test/test.dart';

/// gh-1948: a RUNNING background child had no session file at all — the
/// transcript flushed only at completion/compaction — so `task_observe`
/// had nothing to resolve and crashed on the placeholder path. The
/// executor now flushes the transcript incrementally at every child turn
/// boundary, so the JSONL exists and grows while the child runs.
void main() {
  final assistant = AssistantMessage(
    content: const [],
    api: 'test-api',
    provider: 'test-provider',
    model: 'test-model',
    usage: Usage.zero,
    stopReason: StopReason.stop,
    timestamp: DateTime.utc(2026),
  );

  /// Turn 1 calls the `read` tool; turn 2 hangs until released, so the
  /// test can observe the RUNNING child mid-flight.
  List<AssistantMessageEvent> toolTurn(String toolName) {
    final call = ToolCall(id: 'call-1', name: toolName, arguments: const {});
    final partial = AssistantMessage(
      content: [call],
      api: 'test-api',
      provider: 'test-provider',
      model: 'test-model',
      usage: Usage.zero,
      stopReason: StopReason.toolUse,
      timestamp: DateTime.utc(2026),
    );
    return [
      StartEvent(partial: assistant),
      ToolCallEndEvent(
        contentIndex: 0,
        toolCall: call,
        partial: partial,
      ),
      DoneEvent(reason: StopReason.toolUse, message: partial),
    ];
  }

  List<AssistantMessageEvent> textTurn(String text) {
    final partial = AssistantMessage(
      content: [TextContent(text: text)],
      api: 'test-api',
      provider: 'test-provider',
      model: 'test-model',
      usage: Usage.zero,
      stopReason: StopReason.stop,
      timestamp: DateTime.utc(2026),
    );
    return [
      StartEvent(partial: assistant),
      TextStartEvent(contentIndex: 0, partial: partial),
      TextDeltaEvent(contentIndex: 0, delta: text, partial: partial),
      DoneEvent(reason: StopReason.stop, message: partial),
    ];
  }

  /// Routes by the last user message; the FIRST call replays the tool
  /// turn, later calls park on [gates] keyed by the matched task text.
  final class _GatedMultiTurnStream {
    final gates = <String, Completer<void>>{};

    void openGate(String taskFragment) =>
        gates.putIfAbsent(taskFragment, Completer.new).complete();

    AssistantMessageEventStream call(
      Model model,
      Context context, {
      CancelToken? cancelToken,
    }) {
      var taskText = '';
      for (final message in context.messages.reversed) {
        if (message is UserMessage) {
          final content = message.content;
          taskText = content is String
              ? content
              : (content as List<ContentBlock>)
                    .whereType<TextContent>()
                    .map((b) => b.text)
                    .join('\n');
          break;
        }
      }
      final stream = AssistantMessageEventStream();
      final isFirstCall = !gates.containsKey(taskText);
      if (isFirstCall) {
        // Register the gate BEFORE turn 1 so the test can open it while
        // turn 2 is pending.
        gates[taskText] = Completer<void>();
        for (final event in toolTurn('read')) {
          stream.push(event);
        }
      } else {
        unawaited(
          gates[taskText]!.future.then((_) {
            for (final event in textTurn('child done')) {
              stream.push(event);
            }
            stream.end();
          }),
        );
        return stream;
      }
      stream.end();
      return stream;
    }
  }

  test('a running child flushes its transcript at the turn boundary',
      () async {
    final env = MemoryExecutionEnv(cwd: '/work');
    final repo = JsonlSessionRepo(fs: env, sessionsRoot: '/sessions');
    final manager = SubagentManager(parentSessionId: 'parent-1');
    final childStream = _GatedMultiTurnStream();
    final config = TaskToolConfig(
      childTools: [
        AgentTool(
          name: 'read',
          description: 'read tool',
          tier: ApprovalTier.read,
          execute: (arguments, cancelToken, onUpdate) async =>
              ToolExecutionResult.text('read result'),
        ),
      ],
      streamFunction: () => childStream.call,
      model: () => Model(
        id: 'm',
        api: 'test-api',
        provider: 'test-provider',
        baseUrl: 'https://example.test',
        contextWindow: 100000,
        maxTokens: 4096,
      ),
      subagentManager: manager,
      childSessionFactory: (parentId, childId) => repo.create(
        JsonlSessionCreateOptions(
          cwd: '/work',
          metadata: {
            'agent': 'subagent',
            'id': childId,
            'parent': parentId,
            'model': 'm',
          },
        ),
      ),
    );
    final tool = taskTool(config: config);

    final spawn = tool.execute(
      {
        'context': 'ctx',
        'background': true,
        'tasks': [
          {'name': 'Slow', 'task': 'multi-turn job'},
        ],
      },
      null,
      null,
    );
    // Wait until the child crossed the first turn boundary (it is now
    // parked on turn 2's gate), then give the fire-and-forget flush a
    // bounded window to land.
    final deadline = DateTime.now().add(const Duration(seconds: 10));
    while (!childStream.gates.containsKey('multi-turn job')) {
      if (DateTime.now().isAfter(deadline)) {
        fail('child never reached its second turn');
      }
      await Future<void>.delayed(Duration.zero);
    }
    const flushWait = Duration(seconds: 10);
    final flushDeadline = DateTime.now().add(flushWait);
    while (manager['Slow']!.sessionId == 'parent-1/Slow') {
      if (DateTime.now().isAfter(flushDeadline)) {
        fail('turn-boundary flush never attached the child session');
      }
      await Future<void>.delayed(const Duration(milliseconds: 5));
    }

    // The transcript exists while the child is STILL RUNNING and carries
    // the first turn's messages.
    expect(manager['Slow']!.status, SubagentStatus.running);
    final handle = manager['Slow']!;
    final messages = await jsonlChildMessageReader(env)(
      handle.sessionId,
      tail: 10,
    );
    expect(messages, isNotEmpty, reason: 'turn-1 transcript is on disk');

    childStream.openGate('multi-turn job');
    await spawn;
    expect(manager['Slow']!.status, SubagentStatus.completed);
  });

  test('two running children flush independently (per-child isolation)',
      () async {
    final env = MemoryExecutionEnv(cwd: '/work');
    final repo = JsonlSessionRepo(fs: env, sessionsRoot: '/sessions');
    final manager = SubagentManager(parentSessionId: 'parent-1');
    final childStream = _GatedMultiTurnStream();
    final config = TaskToolConfig(
      childTools: [
        AgentTool(
          name: 'read',
          description: 'read tool',
          tier: ApprovalTier.read,
          execute: (arguments, cancelToken, onUpdate) async =>
              ToolExecutionResult.text('read result'),
        ),
      ],
      streamFunction: () => childStream.call,
      model: () => Model(
        id: 'm',
        api: 'test-api',
        provider: 'test-provider',
        baseUrl: 'https://example.test',
        contextWindow: 100000,
        maxTokens: 4096,
      ),
      subagentManager: manager,
      childSessionFactory: (parentId, childId) => repo.create(
        JsonlSessionCreateOptions(
          cwd: '/work',
          metadata: {
            'agent': 'subagent',
            'id': childId,
            'parent': parentId,
            'model': 'm',
          },
        ),
      ),
    );
    final tool = taskTool(config: config);

    final spawn = tool.execute(
      {
        'context': 'ctx',
        'background': true,
        'tasks': [
          {'name': 'One', 'task': 'job one'},
          {'name': 'Two', 'task': 'job two'},
        ],
      },
      null,
      null,
    );
    final deadline = DateTime.now().add(const Duration(seconds: 10));
    while (!(childStream.gates.containsKey('job one') &&
        childStream.gates.containsKey('job two'))) {
      if (DateTime.now().isAfter(deadline)) {
        fail('children never reached their second turns');
      }
      await Future<void>.delayed(Duration.zero);
    }
    const flushWait = Duration(seconds: 10);
    final flushDeadline = DateTime.now().add(flushWait);
    while (manager['One']!.sessionId == 'parent-1/One' ||
        manager['Two']!.sessionId == 'parent-1/Two') {
      if (DateTime.now().isAfter(flushDeadline)) {
        fail('turn-boundary flush never attached both child sessions');
      }
      await Future<void>.delayed(const Duration(milliseconds: 5));
    }

    expect(manager['One']!.sessionId, isNot(manager['Two']!.sessionId));
    for (final id in ['One', 'Two']) {
      final messages = await jsonlChildMessageReader(env)(
        manager[id]!.sessionId,
        tail: 10,
      );
      expect(messages, isNotEmpty);
    }

    childStream.openGate('job one');
    childStream.openGate('job two');
    await spawn;
    expect(manager['One']!.status, SubagentStatus.completed);
    expect(manager['Two']!.status, SubagentStatus.completed);
  });
}

